mapper:

    SELECT COALESCE(MAX(CONT_REL_NO), 10000) + 1
      FROM T_CONT_REL



    SELECT COALESCE(MAX(CONT_REL_SEQ), 0) + 1
      FROM T_CONT_REL
     WHERE
        CONT_REL_NO = #{contRelNo};


<select id="selectContRel" 
    parameterType="com.albee.albeepoint.mapper.contract.ContRelSearchDto" 
    resultType="com.albee.albeepoint.mapper.contract.ContRelDto>
    SELECT
        CONT_REL_NO
        ,CONT_REL_SEQ
        ,CONT_REL_GB_CD
        ,CONT_ROLE
        ,CONT_NO
        ,LINK_CONT_NO
        ,CONT_REL_INFO
        ,CONT_REL_USE_YN
        ,REG_USER_ID
        ,REG_DT
        ,LAST_MOD_USER_ID
        ,LAST_MOD_DT
    FROM T_CONT_REL
    WHERE 1 = 1

        AND CONT_REL_NO = #{contRelNo}


        AND CONT_REL_SEQ = #{contRelSeq}


        AND CONT_REL_GB_CD = #{contRelGbCd}


        AND CONT_ROLE = #{contRole}


        AND CONT_NO = #{contNo}


        AND LINK_CONT_NO = #{linkContNo}


        AND CONT_REL_USE_YN = #{contRelUseYn}




    SELECT
    COUNT(*)
    FROM T_CONT_REL
    WHERE 1 = 1

        AND CONT_REL_NO = #{contRelNo}


        AND CONT_REL_SEQ = #{contRelSeq}


        AND CONT_REL_GB_CD = #{contRelGbCd}


        AND CONT_ROLE = #{contRole}


        AND CONT_NO = #{contNo}


        AND LINK_CONT_NO = #{linkContNo}


        AND CONT_REL_USE_YN = #{contRelUseYn}




    SELECT
    T.ROW_NUM AS ROW_NUM
    ,T.*
    FROM
    (
    SELECT
    ROW_NUMBER() OVER(ORDER BY CONT_REL_NO, CONT_REL_SEQ) ROW_NUM
        ,CONT_REL_NO
        ,CONT_REL_SEQ
        ,CONT_REL_GB_CD
        ,CONT_ROLE
        ,CONT_NO
        ,LINK_CONT_NO
        ,CONT_REL_INFO
        ,CONT_REL_USE_YN
        ,REG_USER_ID
        ,REG_DT
        ,LAST_MOD_USER_ID
        ,LAST_MOD_DT
    FROM T_CONT_REL
    WHERE 1 = 1

        AND CONT_REL_NO = #{contRelNo}


        AND CONT_REL_SEQ = #{contRelSeq}


        AND CONT_REL_GB_CD = #{contRelGbCd}


        AND CONT_ROLE = #{contRole}


        AND CONT_NO = #{contNo}


        AND LINK_CONT_NO = #{linkContNo}


        AND CONT_REL_USE_YN = #{contRelUseYn}

    ORDER BY CONT_REL_NO, CONT_REL_SEQ
    ) T

        WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
